// Answers each message here in n8n: dedupe by message id, STOP/START, a few plain commands, and a grounded tutor request (OpenAI is called by the next nodes).
// Remembers only: message ids (48 h), hashed numbers that sent STOP, and a per-day tutor counter per hashed number. No message text is stored.
// Pure JavaScript HMAC-SHA256, so this node needs no extra n8n server setting.
const wlBytes=s=>{if(typeof s!=="string")return s;const o=[];for(let i=0;i<s.length;i++){let c=s.charCodeAt(i);if(c>=0xd800&&c<0xe000){const d=i+1<s.length?s.charCodeAt(i+1):0;if(c<0xdc00&&d>=0xdc00&&d<0xe000){c=0x10000+((c-0xd800)<<10)+(d-0xdc00);i++}else c=0xfffd}
if(c<0x80)o.push(c);else if(c<0x800)o.push(0xc0|c>>6,0x80|c&63);else if(c<0x10000)o.push(0xe0|c>>12,0x80|c>>6&63,0x80|c&63);else o.push(0xf0|c>>18,0x80|c>>12&63,0x80|c>>6&63,0x80|c&63)}return Uint8Array.from(o)};
const wlSha=m=>{const P=[];for(let n=2;P.length<64;n++)if(P.every(p=>n%p))P.push(n);
const fr=x=>Math.floor((x-Math.floor(x))*4294967296)>>>0;const K=P.map(p=>fr(Math.pow(p,1/3)));const H=P.slice(0,8).map(p=>fr(Math.sqrt(p)));
const l=m.length,n=((l+9+63)>>6)<<6,b=new Uint8Array(n);b.set(m);b[l]=0x80;const hi=Math.floor(l/0x20000000),lo=(l<<3)>>>0;
[hi,lo].forEach((v,k)=>{for(let j=0;j<4;j++)b[n-8+k*4+j]=(v>>>(24-8*j))&255});
const w=new Array(64),r=(x,k)=>(x>>>k)|(x<<(32-k));
for(let o=0;o<n;o+=64){for(let i=0;i<16;i++)w[i]=((b[o+4*i]<<24)|(b[o+4*i+1]<<16)|(b[o+4*i+2]<<8)|b[o+4*i+3])>>>0;
for(let i=16;i<64;i++){const a=w[i-15],c=w[i-2];w[i]=(w[i-16]+(r(a,7)^r(a,18)^(a>>>3))+w[i-7]+(r(c,17)^r(c,19)^(c>>>10)))>>>0}
let [a,c,d,e,f,g,h,i2]=H;
for(let i=0;i<64;i++){const t1=(i2+(r(f,6)^r(f,11)^r(f,25))+((f&g)^(~f&h))+K[i]+w[i])>>>0,t2=((r(a,2)^r(a,13)^r(a,22))+((a&c)^(a&d)^(c&d)))>>>0;i2=h;h=g;g=f;f=(e+t1)>>>0;e=d;d=c;c=a;a=(t1+t2)>>>0}
[a,c,d,e,f,g,h,i2].forEach((v,i)=>{H[i]=(H[i]+v)>>>0})}
const out=new Uint8Array(32);H.forEach((v,i)=>{for(let j=0;j<4;j++)out[4*i+j]=(v>>>(24-8*j))&255});return out};
const wlHmacHex=(key,msg)=>{let k=wlBytes(key);if(k.length>64)k=wlSha(k);const ip=new Uint8Array(64).fill(0x36),op=new Uint8Array(64).fill(0x5c);for(let i=0;i<k.length;i++){ip[i]^=k[i];op[i]^=k[i]}
const m=wlBytes(msg),a=new Uint8Array(64+m.length);a.set(ip);a.set(m,64);const inner=wlSha(a),b=new Uint8Array(96);b.set(op);b.set(inner,64);return Array.from(wlSha(b),x=>("0"+x.toString(16)).slice(-2)).join("")};
const wlSame=(a,b)=>{if(a.length!==b.length)return false;let d=0;for(let i=0;i<a.length;i++)d|=a.charCodeAt(i)^b.charCodeAt(i);return d===0};
const wlNonce=()=>{let s="";for(let i=0;i<32;i++)s+=Math.floor(Math.random()*16).toString(16);return s};

const COURSES=[{"id":"filmmaking","name":"AI Filmmaking","topics":[{"title":"Make us feel something in one sentence","skill":"Story & emotion","idea":"Start with a person who wants something. Give them a meaningful obstacle and a choice that reveals character. A tool can generate a beautiful image; your story must give the image a reason to exist."},{"title":"Tell a silent story in six shots","skill":"Visual storytelling","idea":"Each shot should reveal information or change a feeling. Plan who is looking, what they see and how they react. Keep screen direction, props, wardrobe and light consistent."},{"title":"Choose what to shoot and what to generate","skill":"Hybrid production","idea":"Assign a reason to every production choice. Shoot the performances and details you can capture well. Use AI for planning or suitable inserts when it adds value. Match light, lens perspective and colour across elements."},{"title":"Write dialogue where nobody says what they mean","skill":"Dialogue & subtext","idea":"Subtext is the meaning under the words. People rarely say their deepest feeling out loud, so give each character a surface topic (a charger, a bag, a snack) and a hidden want."},{"title":"Direct an actor with actions, not emotions","skill":"Directing performance","idea":"Telling an actor to “look sad” asks them to fake a result. Give them an action instead: a verb or an intention they can really try, such as to hide, to avoid, to postpone, or to convince."},{"title":"Plan a location and its light on no budget","skill":"Location & light","idea":"A location plan names the time of day, the light you will use, the permission you need and the safety risks. Visit at the planned hour first and note where the sun, shop lights and shadows fall."},{"title":"Design the sound of one scene","skill":"Sound design","idea":"Sound tells the audience things the picture cannot: what is outside the frame, how big a space is, and what a character feels."},{"title":"Cut a 30-second sequence to build tension","skill":"Editing rhythm","idea":"Pace is how fast the viewer receives new information. Tension builds when shots get shorter, closer and more specific as the goal gets nearer. Cut anything that does not push the story or the pressure."},{"title":"Build a one-day shoot schedule and budget","skill":"Production planning","idea":"A schedule orders scenes by location and light, not by story order, so the crew travels less. Set a call time, add meal and rest breaks, and keep spare time between moves."},{"title":"Pitch your short film on one page","skill":"Film pitching","idea":"A good pitch lets a stranger see the film quickly. State a logline (one sentence with a character, a want and an obstacle), the audience, how live action and AI-assisted work will be combined, and one honest risk with a fix."}]},{"id":"storytelling","name":"AI-powered Visual Storytelling","topics":[{"title":"Tell one clear story in three frames","skill":"Visual narrative","idea":"Give each frame one job: reveal a relatable problem, show a change, and invite a next step. Decide what the audience should feel before choosing colours or an AI image tool. Use one visual idea that connects all three frames."},{"title":"Give AI a visual brief with a point of view","skill":"Visual direction","idea":"Define the subject, action, setting, composition, mood and continuity. Include constraints such as no invented endorsements or unreadable generated text."},{"title":"Link audience, feeling and action in one line","skill":"Core message","idea":"A strong visual story starts with three choices: one audience, one feeling and one action. Pick the feeling you want them to have, such as curiosity or belonging, and the one thing you want them to do next."},{"title":"Plan a poster the eye can read in seconds","skill":"Visual composition","idea":"Good composition gives the eye one place to start. Choose a single focal point, make it stand out through size, contrast or empty space around it, and decide where the eye travels next, usually from the main image to the headline…"},{"title":"Choose colour and type people can actually read","skill":"Accessible design","idea":"Choose a colour mood that fits the audience, such as warm and hopeful, then check that text stands out clearly from its background. Dark text on a light background, or the reverse, is usually safer than two mid-tones."},{"title":"Turn three numbers into one honest chart story","skill":"Data storytelling","idea":"Start with the finding, not the chart: write the headline as one plain sentence about what changed. Pick the chart type that shows that change simply, such as a line or bars for change over time."},{"title":"Plan a five-slide carousel with one idea each","skill":"Carousel structure","idea":"A carousel works like a short story: a hook that stops the scroll, a build that adds interest, proof that the claim is believable, and an invitation that tells people what to do."},{"title":"Review an AI image before you use it","skill":"Image critique","idea":"Review every AI image before using it, with a short checklist. Look for odd hands, faces or objects, text that is misspelt or meaningless, a style that does not match your brand, stereotypes or missing groups, and questions about…"},{"title":"Pitch an idea in three persuasive slides","skill":"Pitch storytelling","idea":"A short pitch works best in this order: problem, insight, ask. The problem makes the audience feel the need, the insight shows what you noticed that others missed, and the ask says exactly what you want them to approve."},{"title":"Storyboard a five-frame campaign in words","skill":"Campaign storyboard","idea":"A campaign storyboard connects everything you have practised: one audience, one feeling, one action, a clear order of frames and a visual detail that repeats."}]},{"id":"marketing","name":"AI Digital Marketing","topics":[{"title":"Turn a customer problem into a clear offer","skill":"Customer insight","idea":"A useful offer connects one specific customer, one urgent problem, and one believable outcome. Use AI to explore variations, then remove claims you cannot prove. The customer should know what to do next."},{"title":"Write a campaign brief an AI can actually use","skill":"AI briefing","idea":"Specify the audience, problem, evidence, tone, constraints and output format. Ask for alternatives, then judge them against a rubric. Never ask the model to invent customer results."},{"title":"Design a follow-up that earns a reply","skill":"Lead conversion","idea":"Reduce the next step. Answer a likely practical question, provide one helpful detail, and ask one easy question. Respect opt-outs and WhatsApp messaging rules."},{"title":"Ask customers fair questions, not leading ones","skill":"Customer research","idea":"A leading question hints at the answer you hope to hear, so people agree to be polite. A yes/no question gives you one word and no reasons."},{"title":"Test one change at a time in an A/B test","skill":"Message testing","idea":"An A/B test compares two versions that differ in exactly one thing, such as the headline or the call to action. If you change several things, you cannot tell which change caused the result."},{"title":"Choose one channel and justify the choice","skill":"Channel choice","idea":"Pick a channel by asking three questions. Where does this audience already spend time and pay attention? What does it cost in money and effort for you? Can you measure what it brings? A channel that fits the audience but cannot…"},{"title":"Find the number that deserves your effort first","skill":"Measuring results","idea":"Not every number tells you the same thing. Clicks show interest, conversations show contact, and qualified enquiries show people who might really buy. To find cost per qualified enquiry, divide total spend by qualified enquiries."},{"title":"Plan two weeks of content you can really keep up","skill":"Content planning","idea":"A content plan starts with one theme, such as “gifts made by hand”, so every post supports the same message. Mix formats, for example a photo, a short reel, a story and a message to existing customers."},{"title":"Spot a risky ad claim and rewrite it honestly","skill":"Responsible marketing","idea":"Responsible marketing means you can support every claim and treat people fairly. Watch for guarantees you cannot control, fake urgency like “only 3 seats left” when seats are not limited, and testimonials that are invented or…"},{"title":"Capstone: build a one-page campaign plan","skill":"Campaign planning","idea":"A strong campaign plan fits on one page and links its parts together. It names the customer and their problem, a simple offer, one channel, one test, one success metric and one risk."}]},{"id":"development","name":"AI Full-Stack Development","topics":[{"title":"Turn a vague idea into a testable feature","skill":"Product thinking","idea":"Start with the smallest complete user action. Define required inputs, success, failure and what must be private. Ask AI for an implementation only after the behaviour is explicit."},{"title":"Review AI-generated code before it ships","skill":"Code review","idea":"Treat browser input as untrusted. Derive identity from a verified server session and prices from a trusted catalogue. Validate inputs and test negative cases, including another user’s record."},{"title":"Choose the records and fields for a booking system","skill":"Data modelling","idea":"A data model lists the things your app remembers (records) and the facts about each one (fields). Give every record a unique identifier, and decide which field must never repeat, such as one seat in one batch for one student."},{"title":"Define one endpoint before asking AI to build it","skill":"API contract","idea":"An API contract describes one endpoint in words: its action, the inputs it needs, what it returns on success and what it returns on failure."},{"title":"Decide which checks run in the browser and server","skill":"Input validation","idea":"Browser checks give fast, friendly feedback, such as a missing field or a phone number that is too short. They can be bypassed, so they are only a convenience."},{"title":"Debug with AI: find the cause, not just a patch","skill":"Debugging with AI","idea":"Debugging means narrowing down where the problem happens. First reproduce it, then check each stage in order: what the browser sent, whether the server received it, and whether the data was stored."},{"title":"Who you are versus what you may do","skill":"Access control","idea":"Authentication answers who you are, usually by logging in. Authorisation answers what you are allowed to do once the system knows who you are. A logged-in user is not allowed everything."},{"title":"Write three test cases for one booking rule","skill":"Writing tests","idea":"A test case states a situation, the action taken, and the exact result you expect. Cover three kinds: a normal case that should work, a boundary case at the exact limit, and a failure case that should be refused."},{"title":"Plan a safe change with branches and rollback","skill":"Version control","idea":"Version control records every change so you can compare, review and undo it. Work on a separate branch, so the live version stays untouched until the change is ready."},{"title":"Capstone: a pre-launch checklist for the booking app","skill":"Launch readiness","idea":"A pre-launch checklist turns worry into specific questions across five areas: security, tests, privacy, error handling and monitoring."}]}];
const secret=String(cfg.appSecret||"");
if(secret.length<16)throw new Error("Open node 'My Settings (edit here)' and fill in appSecret (the Meta app secret), or set WHATSAPP_APP_SECRET on the n8n server.");
const sd=$getWorkflowStaticData("global");
sd.seen=sd.seen||{};sd.stopped=sd.stopped||{};sd.tutor=sd.tutor||{};
const nowMs=Date.now(),day=new Date(nowMs+19800000).toISOString().slice(0,10);
for(const k of Object.keys(sd.seen))if(nowMs-sd.seen[k]>172800000)delete sd.seen[k];
const ids=Object.keys(sd.seen);if(ids.length>3000)ids.sort((a,b)=>sd.seen[a]-sd.seen[b]).slice(0,ids.length-3000).forEach(k=>delete sd.seen[k]);
for(const k of Object.keys(sd.tutor))if(sd.tutor[k].d!==day)delete sd.tutor[k];
const hashOf=p=>wlHmacHex(secret,"phone:"+String(p).replace(/\D/g,"")).slice(0,24);
const STOP=["stop","unsubscribe","end","pause","optout","opt out","रुको","बंद","ನಿಲ್ಲಿಸಿ"];
const NOT_YET="Link your WhatsLearn account at https://whatslearn.in/settings to use saved missions and progress. You can still ask me questions here.";
const HELP="Ask me a question in your own words. Link your account at https://whatslearn.in/settings to learn with synced missions and progress. STOP pauses messages.";
const WELCOME="Hey! What would you like to learn? Link your account at https://whatslearn.in/settings to continue your saved journey here.";
const stopWords=new Set(["the","and","for","with","what","how","why","can","you","are","this","that","about","explain","mean","does","from","have","into","your","please","tell","help","want","need","know","give","show"]);
const words=t=>(String(t).toLowerCase().match(/[a-z]{4,}/g)||[]).filter(w=>!stopWords.has(w));
function material(q){
  const ws=new Set(words(q));
  const scored=[];
  for(const c of COURSES)for(const t of c.topics){let s=0;for(const w of words(t.title+" "+t.skill))if(ws.has(w))s+=2;for(const w of words(t.idea))if(ws.has(w))s+=1;if(s>0)scored.push({c,t,s});}
  const courseScore={};for(const x of scored)courseScore[x.c.id]=(courseScore[x.c.id]||0)+x.s;
  for(const c of COURSES){let s=0;for(const w of words(c.name+" "+c.id))if(ws.has(w))s+=3;if(s)courseScore[c.id]=(courseScore[c.id]||0)+s}
  const best=Object.keys(courseScore).sort((a,b)=>courseScore[b]-courseScore[a])[0];
  const course=COURSES.find(c=>c.id===best);
  const lessons=scored.sort((a,b)=>b.s-a.s).slice(0,3).map(x=>({course:x.c.name,title:x.t.title,skill:x.t.skill,idea:x.t.idea}));
  return {about:"WhatsLearn teaches practical AI skills in four courses with ten short missions each. Account, points and missions are on https://whatslearn.in. No account facts are available in standalone mode.",courses:COURSES.map(c=>c.name),matchedCourse:course?{name:course.name,topics:course.topics.map(t=>t.title+" ("+t.skill+")")}:null,lessons};
}
const src=$("One Item Per Message").all();
return src.map((it,i)=>{
  const m=it.json,out=o=>({json:o,pairedItem:{item:i}});
  const wamid=String(m.wamid||"");
  if(!wamid)return out({action:"none",reason:"invalid"});
  if(sd.seen[wamid])return out({action:"none",reason:"duplicate"});
  sd.seen[wamid]=nowMs;
  const h=hashOf(m.from),text=String(m.text||"").trim().replace(/\s+/g," ").slice(0,4000),word=text.toLowerCase(),cmd=word.split(" ")[0].replace(/[.!,:;]+$/,"");
  if(STOP.includes(word)){sd.stopped[h]=nowMs;return out({action:"reply",text:"You will not get more messages from WhatsLearn. Send START any time to talk to me again."})}
  if(cmd==="start"&&word===cmd){delete sd.stopped[h];return out({action:"reply",text:WELCOME})}
  if(sd.stopped[h])return out({action:"none",reason:"opted-out"});
  if(m.type!=="text")return out({action:"reply",text:"Please send text. Send HELP to see what I can do."});
  if(!text)return out({action:"none",reason:"empty"});
  if(cmd==="help"||cmd==="menu")return out({action:"reply",text:HELP});
  if(["hi","hello","hey","hii","namaste"].includes(word))return out({action:"reply",text:WELCOME});
  if(["link","today","lesson","next","hint","clue","submit","points","balance","course","check","edit","cancel","remind","streak"].includes(cmd))return out({action:"reply",text:NOT_YET});
  return out({action:"tutor",standalone:true,question:text.slice(0,500),language:"en",maxWords:65,material:material(text),fallback:"I could not reach the mentor just now. Please try again in a minute."});
});
